const payload = $('Webhook').first().json.body.body || {};
const userMessage = (payload.message || "").toString().toLowerCase();

// Detect sales order commands
const isSalesOrder = /create.*sales.*order|new.*sales.*order|add.*sales.*order/i.test(userMessage);

// Detect purchase order commands
const isPurchaseOrder = /create.*purchase.*order|new.*purchase.*order|add.*purchase.*order|create.*po\b/i.test(userMessage);

let route = "other";
if (isSalesOrder) {
  route = "sales_order";
} else if (isPurchaseOrder) {
  route = "purchase_order";
}

return [{ json: { route } }];

const customer = $('Get many Customers').first().json.display_name;
const setItems = $input.all();
const parserProducts = $('AI Agent - Create Sales Order').first().json.output.products || [];

let list = setItems.map(it => {
  const displayName = it.json.display_name || "";

  // Find matching product in AI Agent output
  const match = parserProducts.find(p => {
    const name = (p.product_name || "").toLowerCase();
    return displayName.toLowerCase().includes(name) || name.includes(displayName.toLowerCase());
  });

  const qty = match ? match.quantity : 0;
  return `${displayName} (x${qty})`;
}).join(", ");

return {
  reply: `Sales order created successfully for ${customer} with ${list}.`
};

const msg = $('AI Agent').first().json.output|| "";

// Capture customer name: stop before "with"
const customerMatch = msg.match(/for the customer\s+([A-Za-z\s]+?)(?=\s+with)/i);

// Capture product name inside quotes and quantity after "quantity"
const productRegex = /product\s+"([^"]+)"\s+in\s+quantity\s+(\d+)/gi;
let products = [];
let match;

while ((match = productRegex.exec(msg)) !== null) {
  products.push({
    product_name: match[1].trim(),
    quantity: parseInt(match[2])
  });
}

return [{
  customer_name: customerMatch ? customerMatch[1].trim() : null,
  products: products
}];

return {
  reply: $input.first().json.text|| "Sorry, I didn’t understand."
};

